/**
 * @react-three/fiber 的 JSX 元素类型注册补丁。
 *
 * R3F v9 的 `dist/declarations/src/three-types.d.ts` 只 augment 了 `react` /
 * `react/jsx-runtime` 两个模块的 JSX 命名空间;而本端 tsconfig 是 `"jsx": "preserve"`,
 * TS 在这一档解析的是**全局** `JSX.IntrinsicElements`,于是 `<mesh>` / `<primitive>` /
 * `<meshStandardMaterial>` / `<ambientLight>` 一律报 TS2339(仓库实测 7 处)。
 *
 * 这里只补一处同源声明(extends 的仍是包自己导出的 ThreeElements,不另抄元素表),
 * 让全局 JSX 与 react JSX 拿到同一份类型;元素清单的唯一真相源留在依赖包内。
 */
import type { ThreeElements } from '@react-three/fiber'

declare global {
  namespace JSX {
    interface IntrinsicElements extends ThreeElements {}
  }
}

declare module 'react' {
  namespace JSX {
    interface IntrinsicElements extends ThreeElements {}
  }
}
